$('#startGame').onclick=()=>{updatePreview();state.inventory=[{name:originNames[profile.origin],desc:profile.origin==='A cracked smartphone'?'A relic from another world. Its screen flickers with a date that cannot be.':'A useful modern-world tool, carefully kept.' ,use:profile.origin==='A field first-aid kit'?'heal':'story'}, {name:'Field ration',desc:'Dry, tasteless, and better than nothing.',use:'heal'}, {name:'Unfamiliar headband',desc:'Someone left this at the shrine. It may open doors—or close them.',use:'story'}];state.journal=[{title:'The impossible crossing',text:'A flash of white. The smell of wet cedar. The sky had two moons—or one moon seen through a tear in the world. My phone says the year is wrong by decades.'}];$('#creator').classList.add('hidden');$('#game').classList.remove('hidden');document.title='Out of Time — '+profile.name;render()};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function journal(title,text){state.journal.unshift({title,text})}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)}
function syncHud(){ $('#sideName').textContent=profile.name;$('#avatarLetter').textContent=profile.name.slice(0,1).toUpperCase();$('#hpText').textContent=`${state.hp} / ${state.maxHp}`;$('#hpBar').style.width=`${100*state.hp/state.maxHp}%`;$('#chakraText').textContent=`${state.chakra} / ${state.maxChakra}`;$('#chakraBar').style.width=`${100*state.chakra/state.maxChakra}%`;$('#xpDisplay').textContent=state.xp+' XP';$('#coinDisplay').textContent=state.ryo+' RYO';$('#resolveStat').textContent=state.resolve;$('#insightStat').textContent=state.insight;$('#trustStat').textContent=state.trust;$('#itemCount').textContent=state.inventory.length;$('#journalCount').textContent=state.journal.length;$('#sideLevel').textContent=`${state.xp>=60?'FIELD OPERATIVE':'ROOKIE'} · LV ${1+Math.floor(state.xp/60)}`;let q=state.stage==='arrival'?['A Stranger in the Rain','Find shelter and learn where—and when—you are.','● FIRST CONTACT']:state.stage==='combat'?['The Wrong Place, Wrong Time','Survive the ambush. A fight can end without a corpse.','● SURVIVE']:state.stage==='aftermath'?['An Unwanted Witness','Decide what to do with the wounded stranger.','● MAKE A CHOICE']:['A Note from Tomorrow','Choose what kind of future you will try to make.','● CHAPTER ONE'];$('#questName').textContent=q[0];$('#questDesc').textContent=q[1];$('#questStep').textContent=q[2]}
function header(kicker,title){return `<div class="content-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div><div class="day-tag">LAND OF FIRE<br>YEAR UNKNOWN · DUSK</div></div>`}
function storyView(){let body='';if(state.stage==='arrival')body=`<div class="scene"><div class="scene-content"><div class="scene-label">LAND OF FIRE · OUTSKIRTS · DUSK</div><h3>The rain tastes like iron.</h3><p>Your phone is dead. Your hands are shaking. Beyond the cedar trees, a village glows beneath a mountain carved with enormous stone faces. Then someone cries out from the road.</p></div></div><section class="story-block"><h3>First impressions</h3><p>A wounded shinobi is pinned beneath a fallen branch. A second figure watches from the ridge, masked and armed. The injured stranger sees your clothes and reaches for a kunai. Neither of you knows whether the other is a threat.</p><div class="choices"><button class="story-choice" data-act="help"><b>Help the wounded stranger</b><span>Make yourself vulnerable. A little compassion might earn a little trust.</span><em>+ TRUST · RISKY</em></button><button class="story-choice" data-act="talk"><b>Keep your hands visible and talk</b><span>Ask where you are. Give nobody a reason to panic.</span><em>+ INSIGHT · NONVIOLENT</em></button><button class="story-choice" data-act="hide"><b>Disappear into the trees</b><span>Survival first. Look for an escape route before committing.</span><em>+ RESOLVE · CAUTIOUS</em></button><button class="story-choice" data-act="signal"><b>Use the phone as a signal</b><span>Risk the last of its power to draw attention to yourself.</span><em>UNPREDICTABLE</em></button></div></section>`;
else if(state.stage==='combat')body=combatView();else if(state.stage==='aftermath')body=`<div class="scene"><div class="scene-content"><div class="scene-label">THE ROAD TO THE LEAF · NIGHT</div><h3>Victory is not an answer.</h3><p>The masked attacker is down, breathing but badly hurt. The shinobi from beneath the branch is upright now, one arm held tight against their ribs. They watch you with the wary respect reserved for people who could have done worse.</p></div></div><section class="story-block"><h3>What does your first act in this world say?</h3><p>You have no map, no allies, and no way home. The stranger has a name—Mika—and a warning: the world is heading toward a war nobody can afford.</p><div class="choices"><button class="story-choice" data-act="mercy"><b>Bind the attacker’s wounds</b><span>Even an enemy is a person. Ask Mika to help you keep them alive.</span><em>+ TRUST · + INSIGHT</em></button><button class="story-choice" data-act="question"><b>Demand answers first</b><span>Secure the scene. Find out who sent the attacker and why.</span><em>+ INSIGHT · + RYO</em></button><button class="story-choice" data-act="leave"><b>Get Mika to safety, then leave</b><span>You can’t fix this world on your first night. Get clear, then think.</span><em>+ RESOLVE · + RYO</em></button></div></section>`;
else body=`<div class="scene"><div class="scene-content"><div class="scene-label">CHAPTER ONE · A THREAD IN THE DARK</div><h3>The future has a witness.</h3><p>Mika gives you a place to sleep in the village outskirts—and a name to ask for at first light: Kakashi. Your arrival has already changed one small thing. Whether it matters is up to you.</p></div></div><div class="ending"><div class="eyebrow">Chapter one complete</div><h3>Your story has begun, ${esc(profile.name)}.</h3><p>You crossed worlds, survived your first encounter, and made a choice that will follow you. The larger story is still ahead: train, build trust, and decide what the future deserves. Your progress is saved in this browser.</p><button class="secondary" data-act="continue" style="margin-top:7px">CONTINUE REFLECTING ↗</button></div><section class="story-block"><h3>Your first impression</h3><p>${esc(profile.name)} arrived carrying ${esc(profile.origin.toLowerCase())}, believing that “${esc(profile.belief.toLowerCase())}.” ${state.trust>0?'Mika has begun to trust you.':'Mika is still deciding what to make of you.'} This is only the first chapter.</p></section>`;
return header('Main story · Chapter one',state.stage==='arrival'?'A stranger in the rain':state.stage==='combat'?'An ambush on the road':state.stage==='aftermath'?'After the clash':'A thread in the dark')+body+`<div class="footer-note">A FICTIONAL FAN-MADE ROLEPLAY EXPERIENCE · YOUR CHOICES SHAPE THIS STORY</div>`}
function combatView(){return `<div class="scene"><div class="scene-content"><div class="scene-label">COMBAT · TURN ${state.combatTurn+1}</div><h3>Hold your ground.</h3><p>The masked fighter moves fast, but they are watching you—not trying to kill you. There may still be a way out that doesn’t end in blood.</p></div></div><div class="combat-arena"><div class="combatants"><div><div class="fighter-top"><span>${esc(profile.name.toUpperCase())}</span><span>${state.hp} / ${state.maxHp} HP</span></div><div class="bar"><span style="width:${100*state.hp/state.maxHp}%"></span></div></div><div class="enemy"><div class="fighter-top"><span>MASKED STRANGER</span><span>${state.enemyHp} / 75 HP</span></div><div class="bar"><span style="width:${Math.max(0,100*state.enemyHp/75)}%"></span></div></div></div><div class="combat-log" id="combatLog">${esc(state.flags.log||'A blade flashes in the rain. Choose your move. Your goal is to stop the attack—not to kill.')}</div><div class="combat-actions"><button class="move" data-act="strike">Quick strike<small>12–18 damage · no chakra</small></button><button class="move" data-act="jutsu" ${state.chakra<20?'disabled':''}>${esc(profile.nature)} technique<small>22–30 damage · 20 chakra</small></button><button class="move" data-act="guard">Brace & read<small>Reduce next hit · regain 8 chakra</small></button><button class="move" data-act="retreat">Break away<small>End the fight · take a hit</small></button></div><div class="combat-status">${state.hp<35?'CRITICAL CONDITION · ':''}TACTICAL NOTE: guarding can create an opening.</div></div>`}
function characterView(){return header('Field dossier','Your character')+`<div class="panel-grid"><div class="info-card"><div class="eyebrow">IDENTITY</div><h3>${esc(profile.name)} · ${profile.age}</h3><p>${esc(profile.pronouns)} · ${esc(profile.look)} · ${esc(profile.village)}<br>Modern-world arrival, current status unknown.</p></div><div class="info-card"><div class="eyebrow">CHAKRA AFFINITY</div><h3>${esc(profile.nature)} release</h3><p>Your chakra responds most naturally to ${esc(profile.nature.toLowerCase())}. You’re still learning to shape it. Practice before attempting anything ambitious.</p></div><div class="info-card"><div class="eyebrow">PERSONAL CREED</div><h3>“${esc(profile.belief)}.”</h3><p>What you believe will not always match what you do. That tension is part of who you are becoming.</p></div><div class="info-card"><div class="eyebrow">ATTRIBUTES</div><h3>Earned, not given</h3><p>Resolve <b>${state.resolve}</b> · Insight <b>${state.insight}</b> · Trust <b>${state.trust}</b><br>Experience <b>${state.xp} XP</b> · Ryo <b>${state.ryo}</b></p></div><div class="info-card wide"><div class="eyebrow">A NOTE FROM THE MODERN WORLD</div><h3>What survived the crossing?</h3><p>${esc(profile.origin)}. ${profile.origin==='A cracked smartphone'?'A locked screen, an impossible date, and no signal. It is proof that home existed—and that proof is both comfort and ache.':'A small, practical reminder of your old life. Familiar weight in an unfamiliar world.'}</p></div></div>`}
function mapView(){let done=state.stage==='chapterEnd';return header('Field map · Land of Fire','The road ahead')+`<div class="map-board"><div class="map-line" style="width:22%;left:17%;top:48%;transform:rotate(-20deg)"></div><div class="map-line" style="width:24%;left:38%;top:40%;transform:rotate(25deg)"></div><div class="map-line" style="width:22%;left:61%;top:50%;transform:rotate(-18deg)"></div><span class="map-node current" style="left:8%;top:44%">CEDAR ROAD</span><span class="map-node ${state.stage!=='arrival'?'current':''}" style="left:31%;top:30%">MIKA’S SHELTER</span><span class="map-node ${done?'current':''}" style="left:55%;top:47%">HIDDEN LEAF</span><span class="map-node" style="left:77%;top:30%;opacity:.55">THE HOKAGE TOWER · ?</span><div style="position:absolute;bottom:15px;left:15px;font:9px var(--mono);color:#e2c995">◈ KNOWN TERRITORY</div></div><section class="story-block"><h3>Routes are stories too</h3><p>The map is incomplete. You have only seen the road, Mika’s shelter, and the distant walls of the Hidden Leaf. Further places will open as your story continues. For now, you are here because a stranger chose not to leave you behind.</p></section><div class="panel-grid" style="margin-top:17px"><div class="info-card"><div class="eyebrow">CURRENT LOCATION</div><h3>${state.stage==='arrival'?'Cedar Road':'Mika’s Shelter'}</h3><p>Land of Fire · Dusk, fading into night</p></div><div class="info-card"><div class="eyebrow">TRAVEL STATUS</div><h3>${state.stage==='arrival'?'Exposed':'Safe for tonight'}</h3><p>${state.stage==='arrival'?'No supplies, no escort, and unknown terrain.':'Rest, regroup, and set out at first light.'}</p></div></div>`}
function inventoryView(){return header('Pack & tools','Inventory')+`<div class="info-card"><div class="eyebrow">CARRIED ITEMS · ${state.inventory.length}</div><h3>What made it through</h3>${state.inventory.map((it,i)=>`<div class="inventory-item"><div><b>${esc(it.name)}</b><small>${esc(it.desc)}</small></div><button class="use-btn" data-use="${i}">${it.use==='heal'?'USE':'INSPECT'}</button></div>`).join('')||'<p>Your pack is empty.</p>'}<p style="margin-top:15px;color:#8f9a90;font-size:10px">A careful shinobi carries less than they think they need—and knows what each item is for.</p></div>`}
function journalView(){return header('Personal record · Private','Field journal')+`<div class="info-card"><div class="eyebrow">CHAPTER ONE · ${state.journal.length} ENTRIES</div><h3>Notes to a future self</h3><div style="margin-top:22px">${state.journal.map((e,i)=>`<div class="journal-entry"><div class="eyebrow">ENTRY ${String(state.journal.length-i).padStart(2,'0')}</div><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p></div>`).join('')}</div></div>`}
function render(){syncHud();let content=state.view==='story'?storyView():state.view==='character'?characterView():state.view==='map'?mapView():state.view==='inventory'?inventoryView():journalView();$('#mainContent').innerHTML=content;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.view))}
$$('.nav-btn').forEach(b=>b.onclick=()=>{state.view=b.dataset.tab;render()});$('#saveBtn').onclick=()=>{localStorage.setItem('shinobi-chronicles-save',JSON.stringify({profile,state}));toast('Journey saved on this device.')};

