$$('.nav-btn').forEach(b=>b.onclick=()=>{state.view=b.dataset.tab;render()});$('#saveBtn').onclick=()=>{localStorage.setItem('shinobi-chronicles-save',JSON.stringify({profile,state}));toast('Journey saved on this device.')};
function startEncounter(choice){if(choice==='help'){state.trust++;state.hp-=5;state.flags.opening='You tried to free the stranger first. The masked fighter took advantage of your hesitation, but Mika saw what you risked.'}else if(choice==='talk'){state.insight++;state.chakra=Math.min(state.maxChakra,state.chakra+8);state.flags.opening='You kept your hands visible and asked a question. The answer was cut short by the masked fighter’s lunge.'}else if(choice==='hide'){state.resolve++;state.flags.opening='You found cover and a better angle. When the attacker turned on Mika, you chose to step back in.'}else{state.insight++;state.flags.opening='Your dead phone sparked in your palm. The masked fighter mistook the flash for a signal and rushed you.'}state.stage='combat';state.flags.log=state.flags.opening+' Your turn.';render()}
function opponentTurn(blocked){let hit=blocked?Math.max(3,Math.floor(Math.random()*7)+2):Math.floor(Math.random()*8)+8;state.hp=Math.max(0,state.hp-hit);state.flags.log+=` The attacker counters for ${hit} damage${blocked?'—you were ready for it':''}.`;if(state.hp<=0){state.hp=1;state.flags.log+=' You break contact before the next strike can land.';finishFight(false)}else render()}
function moveFight(move){if(state.stage!=='combat')return;if(move==='retreat'){state.flags.log='You turn the attacker’s momentum aside and break away. Mika covers your escape. The threat is still out there, but you are alive.';state.resolve++;finishFight(false);return}let damage=0,blocked=false;if(move==='strike'){damage=12+Math.floor(Math.random()*7);state.flags.log=`You step in with a quick strike. ${damage} damage.`}if(move==='jutsu'){if(state.chakra<20){toast('Not enough chakra.');return}state.chakra-=20;damage=22+Math.floor(Math.random()*9);state.flags.log=`A rough ${profile.nature.toLowerCase()} technique catches the attacker off guard. ${damage} damage.`}if(move==='guard'){blocked=true;state.chakra=Math.min(state.maxChakra,state.chakra+8);state.flags.log='You brace, watch their shoulders, and let the next move tell you what they intend. +8 chakra.'}state.enemyHp=Math.max(0,state.enemyHp-damage);state.combatTurn++;if(state.enemyHp<=0){state.flags.log+=' The masked fighter drops their weapon and yields.';finishFight(true);return}opponentTurn(blocked)}
function finishFight(won){state.stage='aftermath';state.flags.fightResult=won?'You disarmed the attacker and forced them to yield.':'You broke away with Mika. The attacker escaped into the rain.';if(won){state.xp+=35;state.ryo+=5;state.inventory.push({name:'Dropped kunai',desc:'A plain, well-used tool. Take care how you use it.',use:'story'});journal('First blood, not the last','I faced someone who meant me harm. I chose to stop them, not end them. I still feel the moment in my hands.');toast('Encounter survived · +35 XP · +5 ryo')}else{state.xp+=15;state.ryo+=3;journal('A narrow escape','I did not win the fight, but I kept Mika and myself alive. That will have to count for something.');toast('You escaped · +15 XP · +3 ryo')}render()}
function aftermath(act){if(act==='mercy'){state.trust+=2;state.insight++;state.hp=Math.min(state.maxHp,state.hp+8);journal('Mercy in the mud','I helped Mika bind the attacker’s wounds. They had a reason, though not an excuse. I don’t know what to do with that yet.')}if(act==='question'){state.insight+=2;state.ryo+=4;journal('The name behind the mask','The attacker was looking for a missing courier. Mika paid me a few coins to keep the details quiet until we reach the village.')}if(act==='leave'){state.resolve+=2;state.ryo+=3;journal('A road is still a choice','I chose to get Mika out safely and leave the questions for morning. There are limits to what one person can fix in one night.')}state.stage='chapterEnd';state.xp+=15;toast('Choice recorded · +15 XP');render()}
function postChapter(act){if(act==='continue'){state.stage='epilogue';toast('The night is yours. Make it count.')}if(act==='train'){if(state.flags.trained){toast('You have trained as much as your body can manage tonight.');return}state.chakra=Math.max(0,state.chakra-10);state.resolve++;state.xp+=10;state.flags.trained=true;journal('Practice by lantern-light','Mika taught me a basic stance. I am clumsy, but the movements give my fear somewhere to go.');toast('Training complete · +10 XP · +1 Resolve')}if(act==='talk'){if(state.flags.talked){toast('Mika has fallen asleep. You can talk again at first light.');return}state.trust++;state.flags.talked=true;journal('Mika’s quiet confession','Mika lost a teammate last year. They joined the shinobi corps because sitting with grief felt worse than moving. I told them a little about my old world.');toast('Trust with Mika increased.')}if(act==='rest'){if(state.flags.rested){toast('You already rested. Dawn is close.');return}state.hp=Math.min(state.maxHp,state.hp+25);state.chakra=Math.min(state.maxChakra,state.chakra+20);state.flags.rested=true;journal('Sleep, at last','The shelter roof leaks, the floor is hard, and the world is still strange. But morning comes anyway.');toast('Rested · vitality and chakra restored.')}render()}
$('#mainContent').addEventListener('click',e=>{let b=e.target.closest('[data-act],[data-use]');if(!b)return;if(b.dataset.use!==undefined){let i=Number(b.dataset.use),item=state.inventory[i];if(!item)return;if(item.use==='heal'){let heal=item.name==='First-aid kit'?45:20;let old=state.hp;state.hp=Math.min(state.maxHp,state.hp+heal);if(state.hp===old){toast('Your vitality is already full.');return}state.inventory.splice(i,1);journal('A little care','I used '+item.name.toLowerCase()+' to tend my injuries.');toast(`Recovered ${state.hp-old} vitality.`);render()}else toast(item.desc);return}let a=b.dataset.act;if(state.stage==='arrival'){startEncounter(a);return}if(state.stage==='combat'){moveFight(a);return}if(state.stage==='aftermath'){aftermath(a);return}if(state.stage==='chapterEnd'||state.stage==='epilogue'){postChapter(a);return}});

